<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import api from '../services/api';
import { useAuthStore } from '../stores/auth';
import { RouterLink, useRoute } from 'vue-router';
import { savedAcademicTerm, saveAcademicTerm, academicTermLabel, semesterLabel } from '../services/academic-term';
const auth=useAuthStore(),admin=computed(()=>auth.user?.role==='ADMIN');
const initialTerm=String(useRoute().query.termId||savedAcademicTerm(auth.user?.id)||'');
const mySearch=ref(''),myTerm=ref(initialTerm),meetings=ref([]);
const search=ref(''),page=ref(1),total=ref(0),subjects=ref([]),offerings=ref([]),terms=ref([]),sections=ref([]),faculty=ref([]),students=ref([]),roster=ref([]),selected=ref(null),loading=ref(true),saving=ref(false),error=ref(''),notice=ref('');
const classFilters=ref({search:'',termId:initialTerm,academicYear:'',sectionId:'',facultyId:'',status:'ACTIVE',sort:'code'}),classRows=ref([]),classTotal=ref(0),classPage=ref(1);
watch(myTerm,value=>{if(!admin.value)saveAcademicTerm(auth.user?.id,value);});
watch(()=>classFilters.value.termId,value=>{if(admin.value){saveAcademicTerm(auth.user?.id,value);classPage.value=1;filterClasses();}});
const subjectForm=ref({code:'',name:'',units:3}),offeringForm=ref({subjectId:'',termId:'',sectionId:'',facultyId:''}),enrollmentForm=ref({studentId:'',offeringId:''});
const enrollmentPath=ref('existing'),manualForm=ref({firstName:'',middleName:'',lastName:'',studentNo:'',email:'',contactNumber:'',birthDate:'',sectionId:'',offeringId:''});
const manualClasses=computed(()=>offerings.value.filter(item=>String(item.sectionId)===String(manualForm.value.sectionId)));
const age=computed(()=>{if(!manualForm.value.birthDate)return null;const birth=new Date(`${manualForm.value.birthDate}T00:00:00`);if(!Number.isFinite(birth.getTime()))return null;const now=new Date();let years=now.getFullYear()-birth.getFullYear();if(now.getMonth()<birth.getMonth()||(now.getMonth()===birth.getMonth()&&now.getDate()<birth.getDate()))years--;return years>=0?years:null;});
const shownClasses=computed(()=>offerings.value.filter(item=>(!myTerm.value||String(item.termId)===String(myTerm.value))&&`${item.code} ${item.name}`.toLowerCase().includes(mySearch.value.trim().toLowerCase())));
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function classMeetings(item){return meetings.value.filter(meeting=>meeting.offeringId===item.id).map(meeting=>`${days[meeting.weekday-1]} ${meeting.startTime}–${meeting.endTime} · Room ${meeting.room}`);}
async function loadClasses(){const result=await api.get('/academic/offerings/search',{params:{...classFilters.value,page:classPage.value}});classRows.value=result.data.data.rows;classTotal.value=result.data.data.total;}
async function filterClasses(){error.value='';try{await loadClasses();}catch(e){error.value=e.response?.data?.message||'Could not filter class assignments.';}}
async function load(){loading.value=true;error.value='';try{const calls=[api.get('/academic/offerings'),api.get('/academic/terms')];if(admin.value)calls.push(api.get('/academic/subjects',{params:{search:search.value,page:page.value}}),api.get('/academic/sections'),api.get('/academic/faculty'),api.get('/academic/students'),api.get('/academic/offerings/search',{params:{...classFilters.value,page:classPage.value}}));else calls.push(api.get('/schedule/meetings'));const results=await Promise.all(calls);offerings.value=results[0].data.data;terms.value=results[1].data.data;if(admin.value){subjects.value=results[2].data.data.rows;total.value=results[2].data.data.total;sections.value=results[3].data.data;faculty.value=results[4].data.data;students.value=results[5].data.data;classRows.value=results[6].data.data.rows;classTotal.value=results[6].data.data.total;}else meetings.value=results[2].data.data;}catch(e){error.value=e.response?.data?.message||'Could not load subjects.';}finally{loading.value=false;}}
async function saveSubject(){saving.value=true;error.value='';try{await api.post('/academic/subjects',subjectForm.value);subjectForm.value={code:'',name:'',units:3};notice.value='Subject created.';await load();}catch(e){error.value=e.response?.data?.message||'Could not save subject.';}finally{saving.value=false;}}
async function archiveSubject(subject){if(!window.confirm(`Archive ${subject.code}? Historical class assignments remain available.`))return;saving.value=true;try{await api.patch(`/academic/subjects/${subject.id}`,{name:subject.name,units:subject.units,status:'ARCHIVED'});notice.value='Subject archived.';await load();}catch(e){error.value=e.response?.data?.message||'Could not archive subject.';}finally{saving.value=false;}}
async function saveOffering(){saving.value=true;error.value='';try{await api.post('/academic/offerings',{...offeringForm.value,facultyId:offeringForm.value.facultyId||null});notice.value='Class assignment created.';await load();}catch(e){error.value=e.response?.data?.message||'Could not create class assignment.';}finally{saving.value=false;}}
async function archiveOffering(offering){if(!window.confirm(`Archive the ${offering.code} class assignment? Enrollment history will be retained.`))return;saving.value=true;try{await api.patch(`/academic/offerings/${offering.id}`,{status:'ARCHIVED'});notice.value='Class assignment archived.';selected.value=null;await load();}catch(e){error.value=e.response?.data?.message||'Could not archive class assignment.';}finally{saving.value=false;}}
async function enroll(){saving.value=true;error.value='';try{await api.post('/academic/enrollments',enrollmentForm.value);notice.value='Student enrolled.';await load();}catch(e){error.value=e.response?.data?.message||'Could not enroll student.';}finally{saving.value=false;}}
async function enrollManual(){if(saving.value)return;saving.value=true;error.value='';try{await api.post('/academic/students/manual-enroll',manualForm.value);notice.value='Student record created and enrolled. No portal login was created.';manualForm.value={firstName:'',middleName:'',lastName:'',studentNo:'',email:'',contactNumber:'',birthDate:'',sectionId:'',offeringId:''};await load();}catch(e){error.value=e.response?.data?.message||'Could not create and enroll this student.';}finally{saving.value=false;}}
async function dropEnrollment(student){if(!window.confirm(`Mark ${student.firstName} ${student.lastName} as dropped from ${selected.value.code}?`))return;saving.value=true;try{await api.patch(`/academic/enrollments/${student.id}`,{status:'DROPPED'});notice.value='Enrollment updated.';await showRoster(selected.value);}catch(e){error.value=e.response?.data?.message||'Could not update enrollment.';}finally{saving.value=false;}}
async function showRoster(offering){selected.value=offering;try{roster.value=(await api.get(`/academic/offerings/${offering.id}/roster`)).data.data;}catch(e){error.value=e.response?.data?.message||'Could not load roster.';}}
onMounted(load);
</script>
<template><PortalLayout title="Subjects"><div class="dashboard content-page"><div class="page-heading"><div><p class="eyebrow">ACADEMIC</p><h2>{{admin?'Subject catalog & class assignments':auth.user?.role==='FACULTY'?'My assigned classes':'My subjects'}}</h2><p>A class assignment is a subject assigned to a section for a semester, with its teacher and schedule.</p></div></div>
  <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p><p v-if="loading" class="empty">Loading subjects…</p>
  <template v-else>
    <section v-if="!admin" class="panel"><div class="toolbar"><label>Search my subjects<input v-model="mySearch" placeholder="Subject code or title"/></label><label>Academic term<select v-model="myTerm"><option value="">All terms</option><option v-for="term in terms" :key="term.id" :value="term.id">{{academicTermLabel(term)}}</option></select></label></div></section>
    <section class="panel"><div class="panel-title"><h2>{{admin?'Class assignments':auth.user?.role==='FACULTY'?'My assigned classes':'My subjects'}}</h2><span>{{admin?classTotal:shownClasses.length}} matching</span></div><form v-if="admin" class="toolbar" @submit.prevent="classPage=1;filterClasses()"><label>Search code, title, teacher, or section<input v-model="classFilters.search" placeholder="Search classes"/></label><label>Academic year<select v-model="classFilters.academicYear"><option value="">All years</option><option v-for="year in [...new Set(terms.map(term=>term.academicYear))]" :key="year" :value="year">{{year}}</option></select></label><label>Term<select v-model="classFilters.termId"><option value="">All terms</option><option v-for="term in terms" :key="term.id" :value="term.id">{{academicTermLabel(term)}}</option></select></label><label>Section<select v-model="classFilters.sectionId"><option value="">All sections</option><option v-for="section in sections" :key="section.id" :value="section.id">{{section.program}} · Year {{section.yearLevel}} · {{section.name}}</option></select></label><label>Teacher<select v-model="classFilters.facultyId"><option value="">All teachers</option><option v-for="teacher in faculty" :key="teacher.id" :value="teacher.id">{{teacher.name}}</option></select></label><label>Status<select v-model="classFilters.status"><option value="ACTIVE">Active</option><option value="ARCHIVED">Archived</option></select></label><label>Sort<select v-model="classFilters.sort"><option value="code">Code</option><option value="name">Title</option><option value="newest">Newest</option></select></label><button class="secondary-button">Filter classes</button><button type="button" class="text-button" @click="classFilters={search:'',termId:'',academicYear:'',sectionId:'',facultyId:'',status:'ACTIVE',sort:'code'};classPage=1;filterClasses()">Clear filters</button></form><div v-if="(admin?classRows:shownClasses).length" class="item-grid"><article v-for="offering in admin?classRows:shownClasses" :key="offering.id" class="record-card"><div><span class="eyebrow">{{offering.code}} · {{offering.academicYear}} · {{offering.status}}</span><h3>{{offering.name}}</h3><p>{{offering.units}} units · Section {{offering.section}} · {{semesterLabel(offering.semester)}}</p><p>Teacher: {{offering.faculty||'To be assigned'}}</p><p v-if="admin">{{offering.enrollmentCount}} enrolled</p><p v-for="meeting in classMeetings(offering)" :key="meeting">{{meeting}}</p><p v-if="!classMeetings(offering).length&&!admin">No meeting scheduled yet.</p></div><div class="inline-actions"><button v-if="admin||auth.user?.role==='FACULTY'" class="text-button" @click="showRoster(offering)">View roster</button><RouterLink v-if="!admin" class="text-button" :to="`/${auth.user?.role.toLowerCase()}/schedule?termId=${offering.termId}&subjectId=${offering.subjectId}`">View schedule</RouterLink><button v-if="admin&&offering.status==='ACTIVE'" class="text-button" :disabled="saving" @click="archiveOffering(offering)">Archive class</button></div></article></div><p v-else class="empty">{{admin?'No class assignments match these filters.':offerings.length?'No classes match your search.':'No enrolled subjects yet.'}}</p><div v-if="admin" class="pagination"><button :disabled="classPage===1" @click="classPage--;filterClasses()">Previous</button><span>Page {{classPage}} · {{classTotal}} classes</span><button :disabled="classPage*20>=classTotal" @click="classPage++;filterClasses()">Next</button></div></section>
  <section v-if="selected" class="panel"><div class="panel-title"><h2>{{selected.code}} roster</h2><button class="text-button" @click="selected=null">Close</button></div><div v-if="roster.length" class="record-list"><div v-for="student in roster" :key="student.id" class="record-row"><div><strong>{{student.lastName}}, {{student.firstName}}</strong><span>{{student.studentId}} · {{student.status}}</span></div><button v-if="admin&&student.status==='ENROLLED'" class="text-button" :disabled="saving" @click="dropEnrollment(student)">Mark dropped</button></div></div><p v-else class="empty">No students enrolled.</p></section>
  <template v-if="admin"><section class="panel"><div class="panel-title"><h2>Subject catalog</h2><span>{{total}} active subjects</span></div><form class="toolbar" @submit.prevent="page=1;load()"><label>Search catalog<input v-model="search" placeholder="Code or title"/></label><button class="secondary-button">Search</button></form><div v-if="subjects.length" class="record-list"><div v-for="subject in subjects" :key="subject.id" class="record-row"><div><strong>{{subject.code}} · {{subject.name}}</strong><span>{{subject.units}} units</span></div><button class="text-button" :disabled="saving" @click="archiveSubject(subject)">Archive</button></div></div><p v-else class="empty">No subjects found.</p><div class="pagination"><button :disabled="page===1" @click="page--;load()">Previous</button><span>Page {{page}}</span><button :disabled="page*20>=total" @click="page++;load()">Next</button></div></section>
  <div class="two-panel"><section class="panel"><h2>Add subject</h2><form class="stack-form" @submit.prevent="saveSubject"><label>Code<input v-model="subjectForm.code" required maxlength="30"/></label><label>Title<input v-model="subjectForm.name" required maxlength="180"/></label><label>Units<input v-model.number="subjectForm.units" type="number" min="0.5" max="12" step="0.5" required/></label><button class="primary" :disabled="saving">{{saving?'Saving…':'Create subject'}}</button></form></section><section class="panel"><h2>Create class assignment</h2><form class="stack-form" @submit.prevent="saveOffering"><label>Subject<select v-model="offeringForm.subjectId" required><option value="" disabled>Select subject</option><option v-for="s in subjects" :key="s.id" :value="s.id">{{s.code}} · {{s.name}}</option></select></label><label>Term<select v-model="offeringForm.termId" required><option value="" disabled>Select term</option><option v-for="t in terms" :key="t.id" :value="t.id">{{t.academicYear}} · {{t.semester}}</option></select></label><label>Section<select v-model="offeringForm.sectionId" required><option value="" disabled>Select section</option><option v-for="s in sections" :key="s.id" :value="s.id">{{s.program}} · {{s.yearLevel}}{{s.name}}</option></select></label><label>Assigned teacher<select v-model="offeringForm.facultyId"><option value="">Unassigned</option><option v-for="f in faculty" :key="f.id" :value="f.id">{{f.name}}</option></select></label><button class="primary" :disabled="saving">{{saving?'Saving…':'Create class assignment'}}</button></form></section></div>
  <section class="panel"><h2>Enroll student</h2><div class="theme-options" role="group" aria-label="Enrollment path"><button type="button" class="secondary-button" :class="{selected:enrollmentPath==='existing'}" :aria-pressed="enrollmentPath==='existing'" @click="enrollmentPath='existing'">Existing student record</button><button type="button" class="secondary-button" :class="{selected:enrollmentPath==='manual'}" :aria-pressed="enrollmentPath==='manual'" @click="enrollmentPath='manual'">Create student record</button></div><p class="field-help">Manually created academic records have no portal login. Account linking requires separate identity verification.</p>
    <form v-if="enrollmentPath==='existing'" class="toolbar" @submit.prevent="enroll"><label>Student<select v-model="enrollmentForm.studentId" required><option value="" disabled>Select student</option><option v-for="s in students" :key="s.id" :value="s.id">{{s.studentNo}} · {{s.name}}{{s.userId?'':' (no login)'}}</option></select></label><label>Select class<select v-model="enrollmentForm.offeringId" required><option value="" disabled>Select class</option><option v-for="o in offerings" :key="o.id" :value="o.id">{{o.code}} — Section {{o.section}} — {{o.semester}} {{o.academicYear}} — {{o.faculty||'Teacher pending'}}</option></select></label><button class="primary" :disabled="saving">{{saving?'Saving…':'Enroll'}}</button></form>
    <form v-else class="stack-form narrow-panel" @submit.prevent="enrollManual"><div class="form-grid"><label>First name<input v-model="manualForm.firstName" required maxlength="100"/></label><label>Middle name (optional)<input v-model="manualForm.middleName" maxlength="100"/></label><label>Last name<input v-model="manualForm.lastName" required maxlength="100"/></label></div><div class="form-grid"><label>School/student ID<input v-model="manualForm.studentNo" required maxlength="40" pattern="[A-Za-z0-9-]{2,40}"/></label><label>Email (optional)<input v-model="manualForm.email" type="email" maxlength="190"/></label><label>Contact number (optional)<input v-model="manualForm.contactNumber" type="tel" maxlength="30"/></label></div><label>Date of birth (optional)<input v-model="manualForm.birthDate" type="date"/><span v-if="age!==null" class="field-help">Age: {{age}} years (calculated)</span></label><label>Program, year level, and section<select v-model="manualForm.sectionId" required @change="manualForm.offeringId='' "><option value="" disabled>Select program and section</option><option v-for="s in sections" :key="s.id" :value="s.id">{{s.program}} · Year {{s.yearLevel}} · Section {{s.name}}</option></select></label><label>Select class<select v-model="manualForm.offeringId" required :disabled="!manualForm.sectionId"><option value="" disabled>Select class in this section</option><option v-for="o in manualClasses" :key="o.id" :value="o.id">{{o.code}} · {{o.name}} · {{o.academicYear}} {{o.semester}}</option></select></label><button class="primary" :disabled="saving">{{saving?'Saving…':'Create record and enroll'}}</button></form></section></template></template></div></PortalLayout></template>
